#include <iostream>
#include <stack>
#include <vector>
#include <list>
#include <deque>

template <typename StackType>
void pushElements(StackType& s, int count) {
    for (int i = 0; i < count; ++i) {
        s.push(i);
        std::cout << s.top() << ' ';
    }
    std::cout << '\n';
}

template <typename StackType>
void popElements(StackType& s) {
    while (!s.empty()) {
        std::cout << s.top() << ' ';
        s.pop();
    }
    std::cout << '\n';
}

int main() {
    // Stack using default deque backend
    std::stack<int> dequeStack;
    // Stack using vector backend
    std::stack<int, std::vector<int>> vectorStack;
    // Stack using list backend
    std::stack<int, std::list<int>> listStack;

    std::cout << "Pushing onto dequeStack: ";
    pushElements(dequeStack, 5);
    std::cout << "Pushing onto vectorStack: ";
    pushElements(vectorStack, 5);
    std::cout << "Pushing onto listStack: ";
    pushElements(listStack, 5);

    std::cout << "Popping from dequeStack: ";
    popElements(dequeStack);
    std::cout << "Popping from vectorStack: ";
    popElements(vectorStack);
    std::cout << "Popping from listStack: ";
    popElements(listStack);

    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
#include <functional>

int main() {
    // 1. Standard FIFO queue
    std::queue<double> fifoQueue;
    fifoQueue.push(3.2);
    fifoQueue.push(9.8);
    fifoQueue.push(5.4);

    std::cout << "FIFO queue pop order: ";
    while (!fifoQueue.empty()) {
        std::cout << fifoQueue.front() << ' ';
        fifoQueue.pop();
    }
    std::cout << '\n';

    // 2. Default Max-Heap priority_queue
    std::priority_queue<double> maxPQ;
    maxPQ.push(3.2);
    maxPQ.push(9.8);
    maxPQ.push(5.4);

    std::cout << "Max-Heap pop order: ";
    while (!maxPQ.empty()) {
        std::cout << maxPQ.top() << ' ';
        maxPQ.pop();
    }
    std::cout << '\n';

    // 3. Min-Heap priority_queue using std::greater<double>
    std::priority_queue<double, std::vector<double>, std::greater<double>> minPQ;
    minPQ.push(3.2);
    minPQ.push(9.8);
    minPQ.push(5.4);

    std::cout << "Min-Heap pop order: ";
    while (!minPQ.empty()) {
        std::cout << minPQ.top() << ' ';
        minPQ.pop();
    }
    std::cout << '\n';

    return 0;
}

#include <iostream>
#include <bitset>

int main() {
    // Create a bitset of 8 bits, initialized to all zeros
    std::bitset<8> flags;
    std::cout << "Initial bitset: " << flags << " (count: " << flags.count() << ")\n";

    // Set specific bits
    flags.set(1); // Set bit 1
    flags.set(3); // Set bit 3
    flags.set(7); // Set bit 7
    std::cout << "After setting 1, 3, 7: " << flags << '\n';

    // Toggle bit 3 and reset bit 1
    flags.flip(3);
    flags.reset(1);
    std::cout << "After flip(3) and reset(1): " << flags << '\n';

    // Inspect properties
    std::cout << "Any bit set: " << std::boolalpha << flags.any() << '\n';
    std::cout << "All bits set: " << flags.all() << '\n';
    std::cout << "Bit at index 7 is on: " << flags.test(7) << '\n';

    return 0;
}
